css.value:
* { 
color: --now-color_text--primary;
font-feature-settings: 'liga' off, 'clig' off;
font-family: var(--Typography-Font---now-font-family, Lato);
font-size: var(--Typography-Size-Text-text-md, 16px);
font-style: normal;
font-weight: 400;
line-height: normal;
}

targets.clientTransformScript:
javascript(/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
*/
function evaluateEvent({api, event}) {
	return {
		event: 'Complete step',
		value: {
			Environment: 'Subproduction',
			Skipped: true,
			Step: 'Review Release Notes'
		}
	};
})

